47	int64_t GetElementStorageBits(DataType dtype) {
48	  // Layout aliasing must be reasoned about in logical storage bits per element,
49	  // not in bytes.  For sub-byte dtypes such as fp4, `dtype.bytes()` rounds up
50	  // to 1 and loses the "two fp4 values share one byte" relationship that
51	  // subtype-changing views rely on.
52	  return static_cast<int64_t>(dtype.bits()) * dtype.lanes();
53	}
54	
55	bool ShapesEqual(const Array<PrimExpr> &lhs, const Array<PrimExpr> &rhs,
56	                 arith::Analyzer *analyzer) {
57	  if (lhs.size() != rhs.size()) {
58	    return false;
59	  }
60	  for (size_t i = 0; i < lhs.size(); ++i) {
61	    if (!analyzer->CanProveEqual(lhs[i], rhs[i])) {
62	      return false;
63	    }
64	  }
65	  return true;
66	}
67	
68	Optional<Buffer> FindLayoutAnchorBuffer(const Array<Buffer> &buffers,
69	                                        const Layout &layout,
70	                                        arith::Analyzer *analyzer) {
71	  for (const auto &buffer : buffers) {
72	    if (ShapesEqual(layout->InputShape(), buffer->shape, analyzer)) {
73	      return buffer;
74	    }
75	  }
76	  return Optional<Buffer>();
77	}
