84	class ThreadBindingCollector : public StmtExprVisitor {
85	public:
86	  void VisitStmt_(const AttrStmtNode *op) final {
87	    if (op->attr_key == tirx::attr::thread_extent) {
88	      IterVar iv = Downcast<IterVar>(op->node);
89	      thread_binding_[iv->var.get()] = iv;
90	    }
91	    StmtExprVisitor::VisitStmt_(op);
92	  }
93	
94	  // The thread binding map
95	  std::unordered_map<const VarNode *, IterVar> thread_binding_;
96	};
