109	class BufferUseDefCollector : public IRVisitorWithAnalyzer {
110	public:
111	  BufferUseDefCollector(bool skip_thread_partition)
112	      : skip_thread_partition_(skip_thread_partition) {}
113	
114	  using arith::IRVisitorWithAnalyzer::IRVisitorWithAnalyzer;
115	
116	  void RunInferStep(int cur_infer_id, InferLevel level, bool update_queue,
117	                    LayoutMap &layout_map, const LayoutMap &strict_layout_map,
118	                    std::deque<int> &q, std::vector<bool> &in_queue) {
119	    auto num_infer = infer_list_.size();
120	
121	    // Range check for cur_infer_id
122	    ICHECK_GE(cur_infer_id, 0) << "cur_infer_id is negative, which is invalid.";
123	    ICHECK_LT(cur_infer_id, num_infer)
124	        << "cur_infer_id " << cur_infer_id << " is out of range, must be < "
125	        << num_infer << ".";
126	
127	    // Make sure we can safely access infer_list_[cur_infer_id] and
128	    // thread_var_vec_[cur_infer_id]
129	    auto &next = infer_list_[cur_infer_id];
130	    auto iter_var = thread_var_vec_[cur_infer_id];
131	    auto thread_bounds = thread_bounds_vec_[cur_infer_id];
132	    arith::Analyzer *cur_analyzer = analyzer_vec_[cur_infer_id].get();
133	    auto buffer_oob = buffer_oob_vec_[cur_infer_id];
134	    // Double-check that 'next' is valid
135	    ICHECK(next.defined()) << "infer_list_[" << cur_infer_id
136	                           << "] is null inside run_infer_step.";
137	
138	    // Check iter_var->dom and dom->extent
139	    ICHECK(iter_var.defined())
140	        << "thread_var_vec_[" << cur_infer_id << "] is not defined.";
141	    ICHECK(iter_var->dom.defined())
142	        << "iter_var->dom is not defined for infer_list_[" << cur_infer_id
143	        << "].";
144	    ICHECK(iter_var->dom->extent.defined())
145	        << "iter_var->dom->extent is not defined for infer_list_["
146	        << cur_infer_id << "].";
147	
148	    const int64_t *extent_ptr = as_const_int(iter_var->dom->extent);
149	    ICHECK(extent_ptr != nullptr)
150	        << "iter_var->dom->extent is not a constant integer, which is "
151	           "required for layout inference.";
152	
153	    // Run InferLayout
154	    auto updates = next->InferLayout(LayoutInferArgs{target_,
155	                                                     thread_bounds,
156	                                                     layout_map,
157	                                                     cur_analyzer,
158	                                                     buffer_oob,
159	                                                     {},
160	                                                     bind_var_to_expr_,
161	                                                     false},
162	                                     level);
163	
164	    // Process the returned updates
165	    for (const auto &[buffer, layout] : updates) {
166	      // Basic validity checks
167	      ICHECK(buffer.defined()) << "InferLayout returned an undefined buffer.";
168	      ICHECK(layout.defined()) << "InferLayout returned an undefined layout.";
169	
170	      if (std::count(maca_async_copy_buffers_.begin(),
171	                     maca_async_copy_buffers_.end(), buffer))
172	        continue;
173	
174	      // Helper: propagate inferred layout to alias buffers (same data Var)
175	      auto propagate_alias = [&](const Buffer &src_buffer,
176	                                 const Layout &src_layout) {
177	        if (!buffer_data_to_buffers_.count(src_buffer->data))
178	          return;
179	        const auto &siblings = buffer_data_to_buffers_[src_buffer->data];
180	        for (const auto &sib : siblings) {
181	          if (sib.same_as(src_buffer))
182	            continue;
183	          bool shapes_equal =
184	              src_layout->InputShape().size() == sib->shape.size();
185	          if (shapes_equal) {
186	            for (size_t i = 0; i < src_layout->InputShape().size(); ++i) {
187	              if (!analyzer_.CanProveEqual(src_layout->InputShape()[i],
188	                                           sib->shape[i])) {
189	                shapes_equal = false;
190	                break;
191	              }
192	            }
193	          }
194	          Layout target_layout =
195	              shapes_equal
196	                  ? src_layout
197	                  // Alias buffers may reinterpret the same storage with a
198	                  // different element width.  Reshape the inferred layout using
199	                  // the old/new storage bit ratio so that layout inference
200	                  // keeps the physical storage footprint unchanged while
201	                  // allowing the logical element count to change.
202	                  : src_layout->Reshape(
203	                        sib->shape, &analyzer_,
204	                        Integer(GetElementStorageBits(src_buffer->dtype)),
205	                        Integer(GetElementStorageBits(sib->dtype)));
206	          if (layout_map.count(sib)) {
207	            ICHECK(target_layout->IsEqual(layout_map[sib].get()))
208	                << "Get different layout for alias buffer " << sib
209	                << " (data-shared with " << src_buffer
210	                << ")\n current: " << target_layout->DebugOutput()
211	                << "\n previous: " << layout_map[sib]->DebugOutput();
212	          } else {
213	            layout_map.Set(sib, target_layout);
214	            if (update_queue && use_list_.count(sib)) {
215	              for (int idx : use_list_[sib]) {
216	                EnqueueWithPriority(idx, q, in_queue, cur_infer_id, layout_map);
217	              }
218	            }
219	          }
220	        }
221	      };
222	
223	      if (layout_map.count(buffer)) {
224	        // If new layout contains the old one, update map
225	        if (IsFragmentBuffer(buffer) && level != InferLevel::kStrict &&
226	            !strict_layout_map.count(buffer)) {
227	          // Actually this test has been done in ParallelOp::InferLayout
228	          // already. Just do it again to avoid missing implementations in other
229	          // `TileOperator`s.
230	
231	          auto dst_layout_opt = layout.as<Fragment>();
232	          ICHECK(dst_layout_opt.has_value())
233	              << "Failed to cast layout to Fragment for buffer " << buffer
234	              << ", layout type is " << layout->GetTypeKey();
235	          const auto &dst_layout = dst_layout_opt.value();
236	          auto src_layout_opt = layout_map[buffer].as<Fragment>();
237	          ICHECK(src_layout_opt.has_value())
238	              << "Failed to cast layout_map[buffer] to Fragment for buffer "
239	              << buffer << ", layout type is "
240	              << layout_map[buffer]->GetTypeKey();
241	          const auto &src_layout = src_layout_opt.value();
242	          ICHECK(dst_layout->InputDim() == src_layout->InputDim());
243	          Array<PrimExpr> indices;
244	          indices.reserve(dst_layout->InputDim());
245	          arith::Analyzer inner_analyzer;
246	          for (int i = 0; i < dst_layout->InputDim(); ++i) {
247	            auto x = InputPlaceholder(i);
248	            indices.push_back(x);
249	            // should be literal - literal = 0, any analyzer will work
250	            ICHECK(is_zero(inner_analyzer.Simplify(
251	                dst_layout->InputShape()[i] - src_layout->InputShape()[i])));
252	            inner_analyzer.Bind(x, Range(0, dst_layout->InputShape()[i]));
253	          }
254	          if (ProveFragmentContains(src_layout, dst_layout, indices, indices,
255	                                    inner_analyzer)) {
256	            layout_map.Set(buffer, layout);
257	            // Propagate to alias buffers as well
258	            propagate_alias(buffer, layout);
259	            continue;
260	          }
261	        }
262	
263	        // If already in map, check if they are structurally equal
264	        if (!layout->IsEqual(layout_map[buffer].get())) {
265	          // Try to merge swizzle layouts if both are swizzle layouts
266	          const Layout &existing = layout_map[buffer];
267	          if (!layout.as<Fragment>() && !existing.as<Fragment>()) {
268	            if (auto merged = MergeSwizzleLayouts(existing, layout, buffer)) {
269	              DLOG(WARNING) << "Swizzle layout conflict for buffer " << buffer
270	                            << ", merging to smaller granularity";
271	              layout_map.Set(buffer, merged.value());
272	              propagate_alias(buffer, merged.value());
273	              continue;
274	            }
275	          }
276	          // If not swizzle layouts or merge failed, raise error
277	          LOG(FATAL) << "Get different layout for " << buffer
278	                     << "\n current layout: " << layout->DebugOutput()
279	                     << "\n previous layout: "
280	                     << layout_map[buffer]->DebugOutput();
281	        }
282	        // Ensure aliases are consistent too
283	        propagate_alias(buffer, layout);
284	      } else {
285	        // Otherwise, update map
286	        layout_map.Set(buffer, layout);
287	        // Propagate to alias buffers (may enqueue their users)
288	        propagate_alias(buffer, layout);
289	        if (!update_queue)
290	          continue;
291	
292	        // Check if buffer exists in use_list_
293	        if (!use_list_.count(buffer) && IsFragmentBuffer(buffer)) {
294	          LOG(WARNING) << "Layout inference failed for buffer " << buffer
295	                       << ". "
296	                       << "The buffer cannot be inferred with current layout "
297	                          "inference rules.";
298	          continue;
299	        }
300	
301	        // Push back into BFS queue
302	        for (int idx : use_list_[buffer]) {
303	          ICHECK_GE(idx, 0)
304	              << "Index in use_list_ for buffer " << buffer << " is negative.";
305	          ICHECK_LT(idx, num_infer)
306	              << "Index in use_list_ for buffer " << buffer
307	              << " out of range: " << idx << " >= " << num_infer << ".";
308	
309	          EnqueueWithPriority(idx, q, in_queue, cur_infer_id, layout_map);
310	        }
311	      }
312	    }
313	  };
314	
315	  void FinishInferQueue(InferLevel level, LayoutMap &layout_map,
316	                        const LayoutMap &strict_layout_map, std::deque<int> &q,
317	                        std::vector<bool> &in_queue) {
318	    auto num_infer = infer_list_.size();
319	
320	    while (!q.empty()) {
321	      int cur_infer_id = q.front();
322	      q.pop_front();
323	      // Range check again, just to be safe
324	      ICHECK_GE(cur_infer_id, 0);
325	      ICHECK_LT(cur_infer_id, num_infer);
326	
327	      in_queue[cur_infer_id] = false;
328	      RunInferStep(cur_infer_id, level, true, layout_map, strict_layout_map, q,
329	                   in_queue);
330	    }
331	  };
332	
333	  LayoutInferenceResult Run() {
334	    // Basic consistency check: infer_list_ and thread_var_vec_ should have the
335	    // same size
336	    ICHECK_EQ(infer_list_.size(), thread_var_vec_.size())
337	        << "Size mismatch: infer_list_ and thread_var_vec_ must match in "
338	           "length.";
339	    ICHECK_EQ(thread_bounds_vec_.size(), infer_list_.size())
340	        << "Size mismatch: thread_bounds_vec_ and infer_list_ must match in "
341	           "length.";
342	    ICHECK_EQ(analyzer_vec_.size(), infer_list_.size())
343	        << "Size mismatch: analyzer_vec_ and infer_list_ must match in "
344	           "length.";
345	    ICHECK_EQ(buffer_oob_vec_.size(), infer_list_.size())
346	        << "Size mismatch: buffer_oob_vec_ and infer_list_ must match in "
347	           "length.";
348	    DLOG(INFO) << "[InferLayout] all participating operators:" << '\n';
349	    for (int i = 0; i < infer_list_stmt_.size(); ++i) {
350	      DLOG(INFO) << "    op " << i << ":" << infer_list_stmt_[i] << '\n';
351	    }
352	
353	    // If needed, you can also check that annotated_layout_map_ is not empty, or
354	    // anything else relevant to your setup.
355	
356	    // Copy the annotated layout map to local variable
357	    Map<Buffer, Layout> layout_map = annotated_layout_map_;
358	    Map<Buffer, Layout> strict_layout_map;
359	    int num_infer = infer_list_.size();
360	
361	    // Prepare BFS queue for iterative inference
362	    std::deque<int> q;
363	    std::vector<bool> in_queue(num_infer, true);
364	    for (int i = 0; i < num_infer; i++) {
365	      // Check that each infer_list_ entry is valid
366	      ICHECK(infer_list_[i].defined())
367	          << "infer_list_[" << i
368	          << "] is null. The inference object is not allocated properly.";
369	
370	      // Check that each thread_var_vec_ entry is defined
371	      if (!thread_var_vec_[i].defined() && skip_thread_partition_) {
372	        thread_var_vec_[i] = thread_var_;
373	      }
374	      q.push_back(i);
375	    }
376	
377	    // step 0: set fully replicated layout for floating fragment buffers
378	    // Floating buffers are accessed outside TileOps (e.g., in if conditions),
379	    // so they must be replicated across all threads.
380	    for (const auto &[buffer, thread_bounds] : floating_fragment_buffers_) {
381	      if (layout_map.count(buffer))
382	        continue;
383	      auto frag =
384	          Fragment::FullyReplicated(buffer->shape, thread_bounds->extent)
385	              ->BindThreadRange(thread_bounds);
386	      layout_map.Set(buffer, frag);
387	    }
388	
389	    // step 1: infer strict layout
390	    for (int i = 0; i < num_infer; i++) {
391	      RunInferStep(i, InferLevel::kStrict, false, layout_map, strict_layout_map,
392	                   q, in_queue);
393	    }
394	
395	    for (const auto &[buffer, layout] : layout_map) {
396	      strict_layout_map.Set(buffer, layout);
397	    }
398	
399	    // step 2: infer common layout with BFS
400	    FinishInferQueue(InferLevel::kCommon, layout_map, strict_layout_map, q,
401	                     in_queue);
402	    // step 3: relax constraints to free and re-run
403	    InferInFreeMode(layout_map, strict_layout_map);
404	    // step 4: finalize alias layouts by Var
405	    // For each storage var, if any buffer in the group has a layout,
406	    // propagate (reshape if needed) to the rest to ensure completeness.
407	    for (const auto &[var, buffers] : buffer_data_to_buffers_) {
408	      // Find a representative with existing layout
409	      Optional<Buffer> rep;
410	      Optional<Layout> rep_layout;
411	      for (const auto &buf : buffers) {
412	        if (layout_map.count(buf)) {
413	          rep = buf;
414	          rep_layout = layout_map[buf];
415	          break;
416	        }
417	      }
418	      if (!rep_layout.defined())
419	        continue;
420	      for (const auto &buf : buffers) {
421	        if (!layout_map.count(buf)) {
422	          bool shapes_equal =
423	              rep_layout.value()->InputShape().size() == buf->shape.size();
424	          if (shapes_equal) {
425	            for (size_t i = 0; i < rep_layout.value()->InputShape().size();
426	                 ++i) {
427	              if (!analyzer_.CanProveEqual(rep_layout.value()->InputShape()[i],
428	                                           buf->shape[i])) {
429	                shapes_equal = false;
430	                break;
431	              }
432	            }
433	          }
434	          Layout reshaped =
435	              shapes_equal
436	                  ? rep_layout.value()
437	                  : rep_layout.value()->Reshape(
438	                        buf->shape, &analyzer_,
439	                        Integer(GetElementStorageBits(rep.value()->dtype)),
440	                        Integer(GetElementStorageBits(buf->dtype)));
441	          layout_map.Set(buf, reshaped);
442	        }
443	      }
444	    }
445	
446	    // Check that all local.fragment buffers have inferred layouts
447	    for (const auto &[buffer, _] : use_list_) {
448	      if (IsFragmentBuffer(buffer)) {
449	        ICHECK_NE(layout_map.count(buffer), 0)
450	            << "The layout for fragment " << buffer
451	            << " can not be inferred correctly.";
452	      }
453	    }
454	
455	    // Collect layout info for For nodes
456	    Map<For, Fragment> for_map;
457	    Map<For, PrimExpr> predicate_map;
458	    Map<For, Bool> padding_guard_map;
459	    ICHECK(infer_list_.size() == thread_var_vec_.size())
460	        << "infer_list_ and thread_var_vec_ size mismatch";
461	    for (int i = 0; i < infer_list_.size(); i++) {
462	      TileOperator base_infer = std::move(infer_list_[i]);
463	      auto thread_var = thread_var_vec_[i];
464	
465	      // Check if base_infer is valid
466	      ICHECK(base_infer.defined()) << "Null pointer encountered in "
467	                                      "infer_list_ while collecting for_map.";
468	      if (auto for_infer = base_infer.as<ParallelOpNode>()) {
469	        // Check that the loop layout is defined
470	        ICHECK(for_infer->GetLoopLayout().defined())
471	            << "The Layout for Parallel for cannot be inferred correctly:\n"
472	            << for_infer->GetRoot();
473	        for_map.Set(for_infer->GetRoot(), for_infer->GetLoopLayout());
474	        if (for_infer->LoopLayoutRequiresPaddingGuard()) {
475	          padding_guard_map.Set(for_infer->GetRoot(), Bool(true));
476	        }
477	        // thread_var_ should be defined if we rely on it
478	        ICHECK(thread_var.defined())
479	            << "thread_var is not defined. Cannot retrieve predicate.";
480	
481	        if (auto predicate = for_infer->GetPredicate(thread_var->var)) {
482	          predicate_map.Set(for_infer->GetRoot(), predicate.value());
483	        }
484	      }
485	    }
486	
487	    return {layout_map, for_map, predicate_map, padding_guard_map};
488	  }
489	
490	  void Collect(const PrimFunc &f) {
491	    for (const auto &[_, buffer] : f->buffer_map) {
492	      if (buffer_data_to_buffers_.count(buffer->data)) {
493	        auto buffers = buffer_data_to_buffers_[buffer->data];
494	        buffers.push_back(buffer);
495	        buffer_data_to_buffers_.Set(buffer->data, buffers);
496	      } else {
497	        buffer_data_to_buffers_.Set(buffer->data, {buffer});
498	      }
499	    }
500	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
501	    ICHECK(target.defined())
502	        << "Layout_Inference: Require the target attribute";
503	    target_ = target.value();
504	    this->operator()(f->body);
505	    // Compute floating fragment buffers after collection
506	    ComputeFloatingFragmentBuffers(f->body);
507	  }
508	
509	private:
510	  Map<Var, Buffer> GetBufferMap() const {
511	    Map<Var, Buffer> buffer_map;
512	    for (const auto &[var, buffers] : buffer_data_to_buffers_) {
513	      // Use the first buffer for each var
514	      // TODO(lei): phaseout buffer_map in future.
515	      if (!buffers.empty()) {
516	        buffer_map.Set(var, buffers[0]);
517	      }
518	    }
519	    return buffer_map;
520	  }
521	
522	  // Return true if any buffer that this op (idx) touches already has
523	  // an inferred layout in layout_map. Used to prioritize enqueue order.
524	  bool HasKnownLayoutAnchor(int idx, const LayoutMap &layout_map) const {
525	    auto it = op_touched_buffers_.find(idx);
526	    if (it == op_touched_buffers_.end() || it->second.empty())
527	      return false;
528	    for (const auto &buf : it->second) {
529	      if (layout_map.count(buf))
530	        return true;
531	    }
532	    return false;
533	  }
534	
535	  // Enqueue idx to q with priority if all its buffers already
536	  // have layouts. Also guards against duplicates and self-enqueue.
537	  void EnqueueWithPriority(int idx, std::deque<int> &q,
538	                           std::vector<bool> &in_queue, int cur_infer_id,
539	                           const LayoutMap &layout_map) const {
540	    if (idx == cur_infer_id)
541	      return;
542	    if (idx < 0 || idx >= static_cast<int>(in_queue.size()))
543	      return;
544	    if (in_queue[idx])
545	      return;
546	    in_queue[idx] = true;
547	    if (HasKnownLayoutAnchor(idx, layout_map)) {
548	      q.push_front(idx);
549	    } else {
550	      q.push_back(idx);
551	    }
552	  }
