554	  void VisitExpr_(const CallNode *op) final {
555	    IRVisitorWithAnalyzer::VisitExpr_(op);
556	    // Do not analysis the call node to the global function.
557	    if (op->op.as<GlobalVarNode>())
558	      return;
559	
560	    auto p = ParseOperator(GetRef<Call>(op));
561	    if (p.defined()) {
562	      for (const auto &arg : op->args) {
563	        if (auto buffer = getBufferFromAccessPtr(arg)) {
564	          addToUseList(buffer.value());
565	        } else if (auto buffer = getBufferFromRegion(arg)) {
566	          addToUseList(buffer.value());
567	        }
568	        // Check if the argument uses any Bind variables that reference
569	        // fragment buffers. If so, add those buffers to the use list.
570	        // This handles cases like: a = block_mask_f[i]; T.copy(A[a, 0], ...)
571	        CollectFragmentBuffersFromExpr(arg);
572	      }
573	      // Compute thread_var_ and thread_bounds_
574	      thread_var_vec_.push_back(thread_var_);
575	      thread_bounds_vec_.push_back(CurrentThreadBounds());
576	      analyzer_vec_.push_back(analyzer_.Clone());
577	
578	      // Compute buffer oob for each buffer in the op
579	      if (const auto *copy = p.as<CopyNode>()) {
580	        auto src_tensor = copy->src;
581	        auto dst_tensor = copy->dst;
582	        auto src_range = copy->src_range;
583	        auto dst_range = copy->dst_range;
584	        bool src_oob = false;
585	        bool dst_oob = false;
586	        for (size_t i = 0; i < src_range.size(); i++) {
587	          if (!analyzer_.CanProve(src_range[i]->min + src_range[i]->extent <=
588	                                      src_tensor->shape[i],
589	                                  arith::ProofStrength::kSymbolicBound)) {
590	            src_oob = true;
591	            break;
592	          }
593	        }
594	        for (size_t i = 0; i < dst_range.size(); i++) {
595	          if (!analyzer_.CanProve(dst_range[i]->min + dst_range[i]->extent <=
596	                                      dst_tensor->shape[i],
597	                                  arith::ProofStrength::kSymbolicBound)) {
598	            dst_oob = true;
599	            break;
600	          }
601	        }
602	        buffer_oob_vec_.push_back(src_oob || dst_oob);
603	
604	        if (auto val = copy->annotations.Get("is_async_copy")) {
605	          if (TargetIsMaca(target_) && val->as<IntImmNode>()->value != 0) {
606	            maca_async_copy_buffers_.push_back(dst_tensor);
607	          }
608	        }
609	      } else {
610	        buffer_oob_vec_.push_back(false);
611	      }
612	
613	      // Add the tile operator to infer_list_
614	      infer_list_stmt_.push_back(GetRef<ObjectRef>(op));
615	      infer_list_.push_back(std::move(p));
616	    }
617	  }
618	
619	  Optional<Buffer> getBufferFromAccessPtr(const PrimExpr &expr) {
620	    if (auto bl = expr.as<BufferLoadNode>()) {
621	      return bl->buffer;
622	    }
623	    auto call = expr.as<CallNode>();
624	    if (!call) {
625	      return std::nullopt;
626	    }
627	    if (call->op.same_as(builtin::tvm_access_ptr())) {
628	      auto var_opt = call->args[1].as<Var>();
629	      if (!var_opt.has_value()) {
630	        LOG(WARNING) << "[getBufferFromAccessPtr] args[1] is not a Var, type: "
631	                     << call->args[1]->GetTypeKey();
632	        return std::nullopt;
633	      }
634	      const auto &var = var_opt.value();
635	      if (buffer_data_to_buffers_.count(var)) {
636	        const auto &buffers = buffer_data_to_buffers_[var];
637	        if (!buffers.empty()) {
638	          return buffers[0]; // Return the first buffer
639	        }
640	      }
641	      return std::nullopt;
642	    }
643	    return std::nullopt;
644	  }
645	
646	  Optional<Buffer> getBufferFromRegion(const PrimExpr &expr) {
647	    if (auto call = expr.as<CallNode>()) {
648	      if (call->op.same_as(RegionOp::Get())) {
649	        if (auto bl = call->args[0].as<BufferLoadNode>()) {
650	          return bl->buffer;
651	        }
652	        return std::nullopt;
653	      }
654	    }
655	    return std::nullopt;
656	  }
