658	  void addToUseList(const Buffer &buffer) {
659	    // buffer scope must be local.fragment
660	    if (!IsFragmentBuffer(buffer)) {
661	      return;
662	    }
663	    int infer_idx = infer_list_.size();
664	    if (use_list_.find(buffer) == use_list_.end()) {
665	      use_list_[buffer] = {};
666	    }
667	    use_list_[buffer].push_back(infer_idx);
668	
669	    // Track which buffers this op (infer_idx) touches for prioritization.
670	    // Avoid duplicates.
671	    auto &vec = op_touched_buffers_[infer_idx];
672	    if (std::none_of(vec.begin(), vec.end(),
673	                     [&](const Buffer &b) { return b.same_as(buffer); })) {
674	      vec.push_back(buffer);
675	    }
676	  }
