678	  void VisitStmt_(const ForNode *op) final {
679	    if (op->kind == ForKind::kParallel) {
680	      auto infer = ParallelOp(GetRef<For>(op));
681	      for (const auto &buffer : infer->GetAccessOrder()) {
682	        addToUseList(buffer);
683	      }
684	
685	      PostOrderVisit(op->body, [this](const ObjectRef &node) {
686	        if (auto *buffer_load = node.as<BufferLoadNode>()) {
687	          if (buffer_load->buffer.defined() &&
688	              buffer_load->buffer->data.defined()) {
689	            if (buffer_data_to_buffers_.count(buffer_load->buffer->data)) {
690	              // Check if this buffer is already in the list
691	              auto buffers = buffer_data_to_buffers_[buffer_load->buffer->data];
692	              bool found = false;
693	              for (const auto &buf : buffers) {
694	                if (buf.same_as(buffer_load->buffer)) {
695	                  found = true;
696	                  break;
697	                }
698	              }
699	              if (!found) {
700	                buffers.push_back(buffer_load->buffer);
701	                buffer_data_to_buffers_.Set(buffer_load->buffer->data, buffers);
702	                DLOG(INFO) << "[LayoutInference] BufferStore: added buffer "
703	                           << buffer_load->buffer
704	                           << " buffer.get() = " << buffer_load->buffer.get()
705	                           << " data = " << buffer_load->buffer->data.get();
706	              }
707	            } else {
708	              buffer_data_to_buffers_.Set(buffer_load->buffer->data,
709	                                          {buffer_load->buffer});
710	              DLOG(INFO) << "[LayoutInference] BufferStore: new buffer "
711	                         << buffer_load->buffer
712	                         << " buffer.get() = " << buffer_load->buffer.get()
713	                         << " data = " << buffer_load->buffer->data.get();
714	            }
715	          }
716	        } else if (auto *buffer_store = node.as<BufferStoreNode>()) {
717	          if (buffer_store->buffer.defined() &&
718	              buffer_store->buffer->data.defined()) {
719	            if (buffer_data_to_buffers_.count(buffer_store->buffer->data)) {
720	              auto buffers =
721	                  buffer_data_to_buffers_[buffer_store->buffer->data];
722	              bool found = false;
723	              for (const auto &buf : buffers) {
724	                if (buf.same_as(buffer_store->buffer)) {
725	                  found = true;
726	                  break;
727	                }
728	              }
729	              if (!found) {
730	                buffers.push_back(buffer_store->buffer);
731	                buffer_data_to_buffers_.Set(buffer_store->buffer->data,
732	                                            buffers);
733	                DLOG(INFO) << "[LayoutInference] BufferStore: added buffer "
734	                           << buffer_store->buffer
735	                           << " buffer.get() = " << buffer_store->buffer.get()
736	                           << " data = " << buffer_store->buffer->data.get();
737	              }
738	            } else {
739	              buffer_data_to_buffers_.Set(buffer_store->buffer->data,
740	                                          {buffer_store->buffer});
741	              DLOG(INFO) << "[LayoutInference] BufferStore: new buffer "
742	                         << buffer_store->buffer
743	                         << " buffer.get() = " << buffer_store->buffer.get()
744	                         << " data = " << buffer_store->buffer->data.get();
745	            }
746	          }
747	        }
748	      });
749	      infer_list_stmt_.push_back(GetRef<ObjectRef>(op));
750	      infer_list_.push_back(std::move(infer));
751	      thread_var_vec_.push_back(thread_var_);
752	      thread_bounds_vec_.push_back(CurrentThreadBounds());
753	      analyzer_vec_.push_back(analyzer_.Clone());
754	      buffer_oob_vec_.push_back(false);
755	    } else {
756	      IRVisitorWithAnalyzer::VisitStmt(op->body);
757	    }
758	  }
