760	  void VisitStmt_(const SBlockNode *op) final {
761	    for (auto buffer : op->alloc_buffers) {
762	      if (buffer_data_to_buffers_.count(buffer->data)) {
763	        auto buffers = buffer_data_to_buffers_[buffer->data];
764	        buffers.push_back(buffer);
765	        buffer_data_to_buffers_.Set(buffer->data, buffers);
766	      } else {
767	        buffer_data_to_buffers_.Set(buffer->data, {buffer});
768	      }
769	    }
770	
771	    // First, visit the block body to collect all buffers from
772	    // BufferLoad/BufferStore
773	    IRVisitorWithAnalyzer::VisitStmt_(op);
774	
775	    // After visiting, apply layouts to all collected buffers
776	    if (op->annotations.count(attr::kLayoutMap)) {
777	      // Check if the layout map is Map<Var, Layout>
778	      auto map =
779	          op->annotations.Get(attr::kLayoutMap)->as<Map<Var, Layout>>().value();
780	      for (const auto &[var, layout] : map) {
781	        ICHECK(buffer_data_to_buffers_.count(var))
782	            << "buffer " << var << " is not found in the block";
783	        const auto &buffers = buffer_data_to_buffers_[var];
784	        ICHECK(!buffers.empty()) << "buffer list for " << var << " is empty";
785	        Optional<Buffer> anchor_buffer =
786	            FindLayoutAnchorBuffer(buffers, layout, &analyzer_);
787	        int64_t anchor_bits =
788	            anchor_buffer.defined()
789	                ? GetElementStorageBits(anchor_buffer.value()->dtype)
790	                : GetElementStorageBits(buffers[0]->dtype);
791	        // Apply layout to all buffers associated with this var
792	        for (const auto &buffer : buffers) {
793	
794	          // Reshape the layout to match the buffer's shape
795	          // Check if shapes are structurally equal
796	          bool shapes_equal =
797	              ShapesEqual(layout->InputShape(), buffer->shape, &analyzer_);
798	
799	          if (shapes_equal) {
800	            annotated_layout_map_.Set(buffer, layout);
801	          } else {
802	            auto reshaped_layout =
803	                layout->Reshape(buffer->shape, &analyzer_, Integer(anchor_bits),
804	                                Integer(GetElementStorageBits(buffer->dtype)));
805	            annotated_layout_map_.Set(buffer, reshaped_layout);
806	          }
807	        }
808	      }
809	    }
810	  }
