831	  // following Bind value chains.
832	  void CollectFragmentBuffersFromExpr(const PrimExpr &expr) {
833	    PostOrderVisit(expr, [this](const ObjectRef &node) {
834	      if (auto bl = node.as<BufferLoadNode>()) {
835	        if (IsFragmentBuffer(bl->buffer)) {
836	          addToUseList(bl->buffer);
