838	      } else if (auto var_node = node.as<VarNode>()) {
839	        auto var = GetRef<Var>(var_node);
840	        if (bind_var_to_expr_.count(var)) {
841	          CollectFragmentBuffersFromExpr(bind_var_to_expr_[var]);
842	        }
843	      }
844	    });
845	  }
