911	  // Compute floating fragment buffers after collection is done.
912	  //
913	  // A "floating" fragment buffer is one that has accesses outside of any
914	  // TileOp (Copy, Gemm, Reduce, Parallel, etc.). For example:
915	  //
916	  //   T.copy(BlockMask[by, :], block_mask_f)  // block_mask_f accessed IN
917	  //   TileOp for i in T.Pipelined(N_S):
918	  //       if block_mask_f[i] >= 0:           // block_mask_f accessed OUTSIDE
919	  //       TileOp (floating!)
920	  //           T.copy(A[...], A_shared)
921	  //
922	  // In this example, `block_mask_f[i]` in the if-condition is a "floating"
923	  // access because it's not inside any TileOp. Such buffers need special
924	  // handling: they must be fully replicated across all threads since the
925	  // access pattern cannot be inferred from TileOp semantics.
926	  //
927	  // This function identifies these buffers by:
928	  // 1. Collecting all IR nodes that are inside TileOps (from infer_list_stmt_)
929	  // 2. Scanning the entire function body for fragment buffer accesses
930	  // 3. Any access not inside a TileOp means the buffer is "floating"
931	  // 4. Recording the thread_bounds at the point of each floating access
932	  void ComputeFloatingFragmentBuffers(const Stmt &func_body) {
933	    // Step 1: Collect all nodes that are inside TileOps
934	    std::unordered_set<const Object *> nodes_in_tileops;
935	    for (const auto &stmt : infer_list_stmt_) {
936	      PostOrderVisit(stmt, [&](const ObjectRef &node) {
937	        nodes_in_tileops.insert(node.get());
938	      });
939	    }
940	
941	    // Step 2: Use a visitor to scan for floating accesses while tracking thread
942	    // context
943	    class FloatingBufferCollector : public IRVisitorWithAnalyzer {
944	    public:
945	      FloatingBufferCollector(
946	          const std::unordered_set<const Object *> &nodes_in_tileops,
947	          std::unordered_map<Buffer, Range, ObjectPtrHash, ObjectPtrEqual>
948	              &floating_buffers)
949	          : nodes_in_tileops_(nodes_in_tileops),
950	            floating_buffers_(floating_buffers) {}
951	
952	      void VisitStmt_(const AttrStmtNode *op) final {
953	        if (op->attr_key == tirx::attr::thread_extent) {
954	          IterVar iv = Downcast<IterVar>(op->node);
955	          if (iv->thread_tag == "threadIdx.x") {
956	            thread_var_ = iv;
957	          }
958	        }
959	        IRVisitorWithAnalyzer::VisitStmt_(op);
960	      }
961	
962	      void VisitExpr_(const BufferLoadNode *op) final {
963	        CheckFloatingAccess(op->buffer, op);
964	        IRVisitorWithAnalyzer::VisitExpr_(op);
965	      }
966	
967	      void VisitStmt_(const BufferStoreNode *op) final {
968	        CheckFloatingAccess(op->buffer, op);
969	        IRVisitorWithAnalyzer::VisitStmt_(op);
970	      }
971	
972	    private:
973	      void CheckFloatingAccess(const Buffer &buffer, const Object *node) {
974	        if (!IsFragmentBuffer(buffer))
975	          return;
976	        if (nodes_in_tileops_.find(node) != nodes_in_tileops_.end())
977	          return;
978	        // This is a floating access - record buffer with current thread_bounds
979	        if (floating_buffers_.find(buffer) != floating_buffers_.end())
980	          return; // Already recorded
981	        floating_buffers_[buffer] = CurrentThreadBounds();
982	      }
983	
984	      Range CurrentThreadBounds() const {
985	        return ComputeThreadBounds(thread_var_, analyzer_);
986	      }
987	
988	      const std::unordered_set<const Object *> &nodes_in_tileops_;
989	      std::unordered_map<Buffer, Range, ObjectPtrHash, ObjectPtrEqual>
990	          &floating_buffers_;
991	      IterVar thread_var_;
992	    };
993	
994	    FloatingBufferCollector collector(nodes_in_tileops,
995	                                      floating_fragment_buffers_);
996	    collector(func_body);
997	
998	    // Debug log floating fragment buffers
999	    if (!floating_fragment_buffers_.empty()) {
1000	      DLOG(INFO)
1001	          << "Floating fragment buffers (have accesses outside TileOps):";
1002	      for (const auto &[buffer, thread_bounds] : floating_fragment_buffers_) {
1003	        DLOG(INFO) << "    " << buffer
1004	                   << " with thread_bounds: " << thread_bounds;
1005	      }
1006	    }
1007	  }
