1014	  // Fragment buffers that have accesses outside of TileOps.
1015	  // These "floating" buffers need fully replicated layouts since their
1016	  // access patterns cannot be inferred from TileOp semantics.
1017	  // Maps buffer -> thread_bounds at the point of floating access.
1018	  // See ComputeFloatingFragmentBuffers() for detailed explanation.
1019	  std::unordered_map<Buffer, Range, ObjectPtrHash, ObjectPtrEqual>
1020	      floating_fragment_buffers_;
1021	  std::unordered_map<Buffer, std::vector<int>, ObjectPtrHash, ObjectPtrEqual>
1022	      use_list_;
