1030	  std::vector<Range> thread_bounds_vec_;
1031	  std::vector<std::unique_ptr<arith::Analyzer>> analyzer_vec_;
1032	  std::vector<bool> buffer_oob_vec_;
1033	  Target target_;
1034	  LayoutMap annotated_layout_map_;
1035	  bool skip_thread_partition_{false};
