1047	  void InferInFreeMode(LayoutMap &layout_map,
1048	                       const LayoutMap &strict_layout_map) {
1049	
1050	    DLOG(INFO) << "Enforced layout maps:" << '\n';
1051	    for (auto &&[k, v] : layout_map) {
1052	      DLOG(INFO) << "    " << k << ": " << v->DebugOutput() << '\n';
1053	    }
1054	    DLOG(INFO) << '\n';
1055	
1056	    // Group operators into connected components
1057	    UnionFind<int> uf;
1058	    for (int i = 0; i < infer_list_.size(); i++) {
1059	      uf.MakeSet(i);
1060	    }
1061	    for (const auto &[buffer, infer_indices] : use_list_) {
1062	      if (infer_indices.empty())
1063	        continue;
1064	
1065	      // Union all infer_list_ indices that share the same Buffer object
1066	      int first_idx = infer_indices[0];
1067	      for (size_t i = 1; i < infer_indices.size(); i++) {
1068	        uf.Union(first_idx, infer_indices[i]);
1069	      }
1070	    }
1071	    // Additionally, union across buffers that share the same underlying
1072	    // buffer->data (Var). This handles cases like reshape where multiple
1073	    // Buffer objects alias the same storage.
1074	    for (const auto &[var, buffers] : buffer_data_to_buffers_) {
1075	      std::vector<int> merged;
1076	      for (const auto &buf : buffers) {
1077	        auto it = use_list_.find(buf);
1078	        if (it != use_list_.end()) {
1079	          const auto &vec = it->second;
1080	          merged.insert(merged.end(), vec.begin(), vec.end());
1081	        }
1082	      }
1083	      if (merged.size() > 1) {
1084	        std::sort(merged.begin(), merged.end());
1085	        merged.erase(std::unique(merged.begin(), merged.end()), merged.end());
1086	        int first = merged[0];
1087	        for (size_t i = 1; i < merged.size(); ++i) {
1088	          uf.Union(first, merged[i]);
1089	        }
1090	      }
1091	    }
1092	
1093	    std::unordered_map<int, std::vector<int>> components;
1094	    for (int i = 0; i < infer_list_.size(); i++) {
1095	      int root = uf.Find(i);
1096	      components[root].push_back(i);
1097	    }
1098	    // Create a map from root to buffers
1099	    std::unordered_map<int, std::vector<Buffer>> components_buffers;
1100	    for (const auto &[buffer, infer_indices] : use_list_) {
1101	      int root = uf.Find(infer_indices[0]);
1102	      components_buffers[root].push_back(buffer);
1103	    }
1104	    // Keep components_buffers for debug purpose
1105	    (void)components_buffers;
1106	
1107	    // For each component, try each op as root, and determine the least
1108	    // replicated one
1109	    std::deque<int> q;
1110	    std::vector<bool> in_queue(infer_list_.size(), false);
1111	
1112	    for (auto &&[root, members] : components) {
1113	      DLOG(INFO) << "======================= processing component " << root
1114	                 << '\n';
1115	      decltype(infer_list_) best_infer_list;
1116	      LayoutMap best_layout_map;
1117	      int64_t min_reg_num = INT64_MAX;
1118	      int min_reg_num_infer_root = -1;
1119	
1120	      // Try each member as the root of inference for this component
1121	      for (int attempt_infer_root : members) {
1122	        DLOG(INFO) << "----------------------- try root " << attempt_infer_root
1123	                   << " members " << members.size() << '\n';
1124	        // Backup the current infer_list_ state
1125	        auto back_infer_list = BackupInferList();
1126	        // Copy the current layout_map for temporary use
1127	        LayoutMap tmp_layout_map = layout_map;
1128	        bool do_update = true;
1129	        try {
1130	          // Run inference starting from attempt_infer_root
1131	          RunInferStep(attempt_infer_root, InferLevel::kFree, true,
1132	                       tmp_layout_map, strict_layout_map, q, in_queue);
1133	          FinishInferQueue(InferLevel::kFree, tmp_layout_map, strict_layout_map,
1134	                           q, in_queue);
1135	
1136	          // After the first search, run inference for all other members in
1137	          // order
1138	          for (int other_infer_root : members) {
1139	            if (other_infer_root != attempt_infer_root) {
1140	              RunInferStep(other_infer_root, InferLevel::kFree, true,
1141	                           tmp_layout_map, strict_layout_map, q, in_queue);
1142	              FinishInferQueue(InferLevel::kFree, tmp_layout_map,
1143	                               strict_layout_map, q, in_queue);
1144	            }
1145	          }
1146	        } catch (const LayoutConflictException &e) {
1147	          do_update = false;
1148	          DLOG(INFO) << "attempt failed due to LayoutConflictException "
1149	                     << e.what() << '\n';
1150	        } catch (const NormalizeIterException &e) {
1151	          do_update = false;
1152	          DLOG(INFO) << "attempt failed due to NormalizeIterException "
1153	                     << e.what() << '\n';
1154	        } catch (const LoopLayoutInjectiveException &e) {
1155	          do_update = false;
1156	          DLOG(INFO) << "attempt failed due to LoopLayoutInjectiveException "
1157	                     << e.what() << '\n';
1158	        }
1159	
1160	        if (do_update) {
1161	          // Compute the total register number for this layout
1162	          int64_t reg_num = 0;
1163	          for (const auto &[buffer, layout] : tmp_layout_map) {
1164	            if (auto frag = layout.as<Fragment>()) {
1165	              int64_t frag_reg_num = 1;
1166	              for (auto i : frag.value()->OutputShape()) {
1167	                auto pci = as_const_int(i);
1168	                ICHECK(pci != nullptr)
1169	                    << "Can not use non-constant range to "
1170	                       "iterate over a fragment/local "
1171	                       "buffer. Non-constant shape expr is: "
1172	                    << i
1173	                    << ". This is possibly because you use symbolic shape when "
1174	                       "accessing a fragment/local buffer.";
1175	                frag_reg_num *= *pci;
1176	              }
1177	              reg_num += frag_reg_num;
1178	            }
1179	          }
1180	          // Update the best plan if this one uses fewer registers
1181	          if (reg_num < min_reg_num ||
1182	              (reg_num == min_reg_num &&
1183	               attempt_infer_root < min_reg_num_infer_root)) {
1184	            best_infer_list =
1185	                BackupInferList(); // Use backup to avoid moving out infer_list_
1186	            best_layout_map = tmp_layout_map;
1187	            min_reg_num = reg_num;
1188	            min_reg_num_infer_root = attempt_infer_root;
1189	          }
1190	        }
1191	        // Restore infer_list_ state for the next attempt
1192	        infer_list_ = std::move(back_infer_list);
1193	      }
1194	      ICHECK(min_reg_num < INT64_MAX) << "no available layout found" << '\n';
1195	      // Apply the best plan for this component
1196	      infer_list_ = std::move(best_infer_list);
1197	      layout_map = best_layout_map;
1198	      DLOG(INFO) << "[InferInFreeMode] Final selection is attempt_infer_root = "
1199	                 << min_reg_num_infer_root << '\n';
1200	    }
1201	  }
1202	};
1203	
1204	class LayoutInferencer : public IRMutatorWithAnalyzer {
1205	public:
1206	  static PrimFunc Substitute(PrimFunc f, bool skip_thread_partition = false) {
1207	    arith::Analyzer analyzer;
1208	    PrimFuncNode *fptr = f.CopyOnWrite();
1209	    fptr->body = ParallelLoopFuser::Fuse(f->body);
1210	    BufferUseDefCollector collector(skip_thread_partition);
1211	    collector.Collect(f);
1212	    auto result = collector.Run();
1213	    LayoutInferencer substituter(result, &analyzer);
1214	    fptr->body = substituter.VisitStmt(f->body);
1215	    return f;
1216	  }
1217	
1218	private:
1219	  LayoutInferencer(const LayoutInferenceResult &result,
1220	                   arith::Analyzer *analyzer)
1221	      : arith::IRMutatorWithAnalyzer(analyzer), result_(result) {};
1222	
1223	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
1224	
1225	  /**
1226	   * @brief Visit and mutate a Block node to attach inferred layout information.
1227	   *
1228	   * Converts the visited Block via the base visitor, asserts that every buffer
1229	   * allocated with scope "local.framgent" has an inferred layout in
1230	   * result_.layout_map, and attaches result_.layout_map to the Block's
1231	   * annotations under attr::kLayoutMap.
1232	   *
1233	   * If any "local.framgent" buffer lacks an entry in result_.layout_map an
1234	   * ICHECK will fail with the offending buffer printed.
1235	   *
1236	   * @return Stmt The (possibly modified) Block statement with the layout-map
1237	   * annotation set.
1238	   */
1239	  Stmt VisitStmt_(const SBlockNode *op) final {
1240	    SBlock block = Downcast<SBlock>(IRMutatorWithAnalyzer::VisitStmt_(op));
1241	
1242	    for (auto buffer : block->alloc_buffers) {
1243	      if (buffer.scope() == "local.framgent") {
1244	        ICHECK(result_.layout_map.count(buffer))
1245	            << "Cannot inference fragment layout for " << buffer;
1246	      }
1247	    }
1248	    auto block_ptr = block.CopyOnWrite();
1249	    block_ptr->annotations.Set(attr::kLayoutMap, result_.layout_map);
1250	    return block;
1251	  }
1252	
1253	  /**
1254	   * @brief Visit and transform For nodes by storing inferred layout information
1255	   *        as annotations instead of expanding the loop.
1256	   *
1257	   * If the For node is present in result_.for_map, this method stores the
1258	   * inferred loop layout and predicate as annotations on the For node, rather
1259	   * than performing loop partition and vectorization.
1260	   *
1261	   * The stored annotations are:
1262	   * - attr::kParallelLoopLayout: The Fragment layout for the parallel loop
1263	   * - attr::kParallelLoopPredicate: The predicate expression (if any)
1264	   * - attr::kParallelLoopRequiresPaddingGuard: Whether inverse lowering must
1265	   *   allow and guard padded points from a ragged SIMT partition
1266	   *
1267	   * @return The For statement with layout annotations attached
1268	   */
1269	  Stmt VisitStmt_(const ForNode *op) final {
1270	    if (!result_.for_map.count(GetRef<For>(op))) {
1271	      return IRMutatorWithAnalyzer::VisitStmt_(op);
1272	    }
1273	
1274	    For for_node = Downcast<For>(IRMutatorWithAnalyzer::VisitStmt_(op));
1275	    auto root = GetRef<For>(op);
1276	
1277	    auto loop_layout = result_.for_map[root];
1278	
1279	    // Store the loop layout as an annotation on the For node (outermost)
1280	    auto for_ptr = for_node.CopyOnWrite();
1281	    for_ptr->annotations.Set(attr::kParallelLoopLayout, loop_layout);
1282	    if (result_.padding_guard_map.count(root)) {
1283	      for_ptr->annotations.Set(attr::kParallelLoopRequiresPaddingGuard,
1284	                               result_.padding_guard_map[root]);
1285	    }
1286	
1287	    // Store the predicate as an annotation if it exists and is not trivially
1288	    // true
1289	    if (result_.predicate_map.count(root)) {
1290	      PrimExpr predicate = analyzer_->Simplify(result_.predicate_map[root]);
1291	      // Only store predicate if it's not trivially true
1292	      if (!is_const_int(predicate, 1)) {
1293	        for_ptr->annotations.Set(attr::kParallelLoopPredicate, predicate);
1294	      }
1295	    }
1296	
1297	    return for_node;
1298	  }
1299	
1300	  Stmt VisitStmt_(const AttrStmtNode *op) final {
1301	    if (op->attr_key == tirx::attr::thread_extent) {
1302	      IterVar iv = Downcast<IterVar>(op->node);
1303	    }
1304	    return IRMutatorWithAnalyzer::VisitStmt_(op);
1305	  }
1306	
1307	private:
1308	  const LayoutInferenceResult result_;
1309	};
1310	
1311	tvm::transform::Pass LayoutInference() {
1312	  using namespace tirx::transform;
1313	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
1314	    ThreadBindingCollector collector;
1315	    collector(f->body);
1316	    bool has_thread_binding = !collector.thread_binding_.empty();
1317	    bool skip_thread_partition = !has_thread_binding;
1318	    f = LayoutInferencer::Substitute(std::move(f), skip_thread_partition);
1319	    // Validate parallel loop layout annotations
1320	    ParallelLoopLayoutValidator::Validate(f->body);
1321	    return f;
1322	  };
1323	  return CreatePrimFuncPass(pass_func, 0, "tl.LayoutInference", {});
1324	}
1325	
1326	TVM_FFI_STATIC_INIT_BLOCK() {
1327	  namespace refl = reflection;
1328	  refl::GlobalDef().def("tl.transform.LayoutInference", LayoutInference);
1329	}
1330	
1331	} // namespace tl
1332	} // namespace tvm
