26	Array<Var> CreateReshapeVars(const Array<PrimExpr> &shape,
27	                             arith::Analyzer *analyzer) {
28	  Array<Var> vars;
29	  vars.reserve(shape.size());
30	  for (size_t i = 0; i < shape.size(); ++i) {
31	    auto var = Var(std::string("n_") + std::to_string(i), shape[i].dtype());
32	    analyzer->Bind(var, Range(0, shape[i]));
33	    vars.push_back(var);
34	  }
