38	PrimExpr ComputeFlatIndex(const Array<PrimExpr> &shape,
39	                          const Array<Var> &vars) {
40	  PrimExpr flat_index = Integer(0);
41	  for (size_t i = 0; i < shape.size(); ++i) {
42	    PrimExpr stride = Integer(1);
43	    for (size_t j = i + 1; j < shape.size(); ++j) {
44	      stride = stride * shape[j];
45	    }
46	    flat_index = flat_index + vars[i] * stride;
47	  }
48	  return flat_index;
49	}
