51	Array<PrimExpr> RecoverOriginalIndices(const Array<PrimExpr> &shape,
52	                                       const PrimExpr &flat_index) {
53	  Array<PrimExpr> original_indices;
54	  PrimExpr remaining = flat_index;
55	  for (size_t i = 0; i < shape.size(); ++i) {
56	    PrimExpr stride = Integer(1);
57	    for (size_t j = i + 1; j < shape.size(); ++j) {
58	      stride = stride * shape[j];
59	    }
60	    original_indices.push_back(floordiv(remaining, stride));
61	    remaining = floormod(remaining, stride);
62	  }
63	  return original_indices;
64	}
