112	Layout TryPackedSubtypeReshape(const LayoutNode *layout_node,
113	                               const Array<PrimExpr> &shape,
114	                               arith::Analyzer *analyzer,
115	                               const PrimExpr &old_elem_bits_expr,
116	                               const PrimExpr &new_elem_bits_expr) {
117	  const int64_t *old_elem_bits = as_const_int(old_elem_bits_expr);
118	  const int64_t *new_elem_bits = as_const_int(new_elem_bits_expr);
119	  if (old_elem_bits == nullptr || new_elem_bits == nullptr) {
120	    return Layout();
121	  }
122	  if (*old_elem_bits <= 0 || *new_elem_bits <= 0) {
123	    return Layout();
124	  }
125	
126	  const Array<PrimExpr> &input_shape = layout_node->InputShape();
127	
128	  // Narrower target element, e.g. uint8 -> fp4.
129	  // One old logical element now contains `pack_factor` new logical elements.
130	  // The generic flat-index reshape would lose this packed-storage structure, so
131	  // we materialize it as an extra trailing output dimension ("pack lane").
132	  if (*old_elem_bits > *new_elem_bits && *old_elem_bits % *new_elem_bits == 0 &&
133	      *new_elem_bits < 8) {
134	    int64_t pack_factor = *old_elem_bits / *new_elem_bits;
135	    Array<Var> new_vars = CreateReshapeVars(shape, analyzer);
136	    PrimExpr flat_index = ComputeFlatIndex(shape, new_vars);
137	    PrimExpr old_flat_index = floordiv(flat_index, Integer(pack_factor));
138	    PrimExpr lane_in_pack = floormod(flat_index, Integer(pack_factor));
139	
140	    Array<PrimExpr> original_indices =
141	        RecoverOriginalIndices(input_shape, old_flat_index);
142	    Array<PrimExpr> new_forward_index =
143	        SubstituteForwardIndex(layout_node->GetForwardIndex(), input_shape,
144	                               original_indices, analyzer);
145	    new_forward_index.push_back(analyzer->Simplify(lane_in_pack));
146	    new_forward_index = RestoreInputPlaceholders(new_forward_index, new_vars);
147	    return Layout(shape, new_forward_index);
148	  }
149	
150	  // Wider target element, e.g. fp4 -> uint8.
151	  // This is only valid if the current layout already exposes the packed
152	  // sub-elements as its last output dimension.  We collapse that trailing pack
153	  // lane back into the logical element index of the wider dtype.
154	  if (*old_elem_bits < *new_elem_bits && *new_elem_bits % *old_elem_bits == 0 &&
155	      *old_elem_bits < 8) {
156	    int64_t pack_factor = *new_elem_bits / *old_elem_bits;
157	    Array<PrimExpr> output_shape = layout_node->OutputShape();
158	    if (output_shape.empty() ||
159	        !analyzer->CanProveEqual(output_shape.back(), Integer(pack_factor))) {
160	      return Layout();
161	    }
162	
163	    Array<Var> new_vars = CreateReshapeVars(shape, analyzer);
164	    PrimExpr flat_index = ComputeFlatIndex(shape, new_vars);
165	    PrimExpr old_flat_index = flat_index * Integer(pack_factor);
166	    Array<PrimExpr> original_indices =
167	        RecoverOriginalIndices(input_shape, old_flat_index);
168	
169	    Array<PrimExpr> expanded_forward_index =
170	        SubstituteForwardIndex(layout_node->GetForwardIndex(), input_shape,
171	                               original_indices, analyzer);
172	    ICHECK_GT(expanded_forward_index.size(), 0);
173	    Array<PrimExpr> new_forward_index;
174	    new_forward_index.reserve(expanded_forward_index.size() - 1);
175	    for (size_t i = 0; i + 1 < expanded_forward_index.size(); ++i) {
176	      new_forward_index.push_back(expanded_forward_index[i]);
177	    }
178	    new_forward_index = RestoreInputPlaceholders(new_forward_index, new_vars);
179	    return Layout(shape, new_forward_index);
180	  }
181	
182	  return Layout();
183	}
