263	
264	    Fragment reshaped(shape, new_forward_index, new_forward_thread,
265	                      fragment_node->ReplicateExtent(), std::nullopt);
266	    if (fragment_node->ThreadRange().defined()) {
267	      reshaped = reshaped->BindThreadRange(fragment_node->ThreadRange());
268	    }
269	    return reshaped;
270	  }
271	
272	  return Fragment();
273	}
