277	static constexpr size_t kMaxPlaceholders = 16;
278	
279	static Var getPlaceholder(const std::string &s) {
280	  // Pre-allocate all possible placeholders so the map is immutable after init.
281	  // C++11 guarantees thread-safe initialization of function-local statics,
282	  // so concurrent reads are safe without a mutex.
283	  static const std::unordered_map<std::string, Var> map = []() {
284	    std::unordered_map<std::string, Var> m;
285	    m.reserve(kMaxPlaceholders + 1);
286	    m["_rep"] = Var("_rep");
287	    for (size_t i = 0; i < kMaxPlaceholders; ++i) {
288	      std::string key{'_', char('i' + i)};
289	      m[key] = Var(key);
290	    }
291	    return m;
292	  }();
293	  auto it = map.find(s);
294	  ICHECK(it != map.end()) << "Unknown placeholder: " << s;
295	  return it->second;
296	}
297	
298	Var ReplicationPlaceholder() { return getPlaceholder("_rep"); }
299	Var InputPlaceholder(size_t idx) {
300	  return getPlaceholder(std::string{'_', char('i' + idx)});
301	}
