367	Array<PrimExpr> LayoutNode::OutputShape() const {
368	  Array<PrimExpr> ret(OutputDim(), 1);
369	  arith::Analyzer analyzer;
370	  UpdateAnalyzer(&analyzer);
371	  for (size_t i = 0; i < ret.size(); i++) {
372	    auto ist = analyzer.int_set(forward_index_[i] + 1);
373	    if (arith::is_neg_inf(ist.min()) && arith::is_pos_inf(ist.max())) {
374	      // Analyzer couldn't form an IntervalSet (e.g. bitwise ops).
375	      // Fall back to ConstIntBound to derive a safe extent.
376	      auto cib = analyzer.const_int_bound(forward_index_[i]);
377	      if (cib->min_value != arith::ConstIntBound::kNegInf &&
378	          cib->max_value != arith::ConstIntBound::kPosInf &&
379	          cib->min_value >= 0) {
380	        // extent = max - min + 1, using 64-bit integer literal
381	        ret.Set(i, Integer(cib->max_value - cib->min_value + 1));
382	      } else {
383	        // Last-resort conservative fallback to avoid OOB/crash
384	        // Prefer to keep dimension from known input_size_ if available.
385	        if (i < input_size_.size()) {
386	          ret.Set(i, input_size_[i]);
387	        } else {
388	          ret.Set(i, Integer(1));
389	        }
390	      }
391	    } else {
392	      ret.Set(i, ist.max());
393	    }
394	  }
395	  return ret;
396	}
