398	Array<PrimExpr> LayoutNode::Forward(const Array<PrimExpr> &vars) const {
399	  if (vars.empty())
400	    return forward_index_;
401	  ICHECK_GE(vars.size(), InputDim());
402	
403	  // Take the last InputDim() elements for transformation
404	  Array<PrimExpr> transform_vars;
405	  for (size_t i = vars.size() - InputDim(); i < vars.size(); i++) {
406	    transform_vars.push_back(vars[i]);
407	  }
408	
409	  Map<Var, PrimExpr> vmap;
410	  for (size_t i = 0; i < InputDim(); i++) {
411	    vmap.Set(InputPlaceholder(i), transform_vars[i]);
412	  }
413	
414	  Array<PrimExpr> transformed = forward_index_.Map(
415	      [&](const PrimExpr &e) { return Substitute(e, vmap); });
416	  // Concatenate with the remaining elements from vars
417	  Array<PrimExpr> result;
418	  for (size_t i = 0; i < vars.size() - InputDim(); i++) {
419	    result.push_back(vars[i]);
420	  }
421	  for (const auto &expr : transformed) {
422	    result.push_back(expr);
423	  }
424	
425	  return result;
426	}
427	
428	Layout LayoutNode::Repeat(int dim, int factor) const {
429	  if (factor < 1) {
430	    TVM_FFI_THROW(ValueError) << "factor must be >= 1, got " << factor;
431	  }
432	  if (factor == 1) {
433	    return GetRef<Layout>(this);
434	  }
435	
436	  const int ndim = static_cast<int>(InputDim());
437	  if (ndim <= 0) {
438	    TVM_FFI_THROW(ValueError) << "Cannot repeat a 0-dim layout";
439	  }
440	  int normalized_dim = dim;
441	  if (normalized_dim < 0) {
442	    normalized_dim += ndim;
443	  }
444	  if (normalized_dim < 0 || normalized_dim >= ndim) {
445	    TVM_FFI_THROW(ValueError)
446	        << "dim out of range: dim=" << dim << ", ndim=" << ndim;
447	  }
448	
449	  Array<PrimExpr> new_input_size = input_size_;
450	  PrimExpr extent_dim = input_size_[normalized_dim];
451	  new_input_size.Set(normalized_dim, extent_dim * Integer(factor));
452	
453	  Map<Var, PrimExpr> vmap;
454	  vmap.Set(InputPlaceholder(normalized_dim),
455	           FloorMod(InputPlaceholder(normalized_dim), extent_dim));
456	
457	  Array<PrimExpr> new_forward_index;
458	  new_forward_index.reserve(OutputDim() + 1);
459	  new_forward_index.push_back(
460	      FloorDiv(InputPlaceholder(normalized_dim), extent_dim));
461	  for (const auto &e : forward_index_) {
462	    new_forward_index.push_back(Substitute(e, vmap));
463	  }
464	
465	  return Layout(new_input_size, new_forward_index);
466	}
467	
468	Layout LayoutNode::Expand(const Array<PrimExpr> &leading_shape) const {
469	  if (leading_shape.empty()) {
470	    return GetRef<Layout>(this);
471	  }
472	
473	  for (size_t i = 0; i < leading_shape.size(); ++i) {
474	    if (auto imm = leading_shape[i].as<IntImm>()) {
475	      if ((*imm)->value <= 0) {
476	        TVM_FFI_THROW(ValueError)
477	            << "leading_shape[" << i << "] must be > 0, got " << (*imm)->value;
478	      }
479	    }
480	  }
481	
482	  const size_t offset = leading_shape.size();
483	
484	  Array<PrimExpr> new_input_size;
485	  new_input_size.reserve(offset + InputDim());
486	  for (const auto &s : leading_shape) {
487	    new_input_size.push_back(s);
488	  }
489	  for (const auto &s : input_size_) {
490	    new_input_size.push_back(s);
491	  }
492	
493	  Map<Var, PrimExpr> vmap;
494	  for (size_t i = 0; i < InputDim(); ++i) {
495	    vmap.Set(InputPlaceholder(i), InputPlaceholder(i + offset));
496	  }
497	
498	  Array<PrimExpr> new_forward_index;
499	  new_forward_index.reserve(offset + OutputDim());
500	  for (size_t i = 0; i < offset; ++i) {
501	    new_forward_index.push_back(InputPlaceholder(i));
502	  }
503	  for (const auto &e : forward_index_) {
504	    new_forward_index.push_back(Substitute(e, vmap));
505	  }
506	
507	  return Layout(new_input_size, new_forward_index);
508	}
509	
510	Fragment FragmentNode::Repeat(const Array<PrimExpr> &repeats,
511	                              bool repeat_on_thread,
512	                              bool lower_dim_first) const {
513	  ICHECK_EQ(repeats.size(), InputDim());
514	  Array<PrimExpr> new_input_size;
515	  Map<Var, PrimExpr> vmap;
516	  for (size_t i = 0; i < InputDim(); i++) {
517	    new_input_size.push_back(input_size_[i] * repeats[i]);
518	    vmap.Set(InputPlaceholder(i),
519	             FloorMod(InputPlaceholder(i), InputShape()[i]));
520	  }
521	
522	  PrimExpr repeats_index = 0, repeat_stride = 1;
523	  if (lower_dim_first) {
524	    for (int i = InputDim() - 1; i >= 0; i--) {
525	      repeats_index +=
526	          repeat_stride * FloorDiv(InputPlaceholder(i), InputShape()[i]);
527	      repeat_stride *= repeats[i];
528	    }
529	  } else {
530	    for (size_t i = 0; i < InputDim(); i++) {
531	      repeats_index +=
532	          repeat_stride * FloorDiv(InputPlaceholder(i), InputShape()[i]);
533	      repeat_stride *= repeats[i];
534	    }
535	  }
536	
537	  if (repeat_on_thread) {
538	    PrimExpr thread_size = ThreadExtent();
539	    auto new_forward_index = forward_index_.Map(
540	        [&](const PrimExpr &e) { return Substitute(e, vmap); });
541	    auto new_forward_thread =
542	        Substitute(forward_thread_, vmap) + thread_size * repeats_index;
543	    return Fragment(new_input_size, new_forward_index, new_forward_thread,
544	                    replicate_size_, std::nullopt);
545	  } else {
546	    ICHECK(OutputDim() == 1);
547	    PrimExpr frag_len = OutputShape()[0];
548	    Array<PrimExpr> new_forward_index = {Substitute(forward_index_[0], vmap) +
549	                                         frag_len * repeats_index};
550	    PrimExpr new_forward_thread = Substitute(forward_thread_, vmap);
551	    return Fragment(new_input_size, new_forward_index, new_forward_thread,
552	                    replicate_size_, std::nullopt);
553	  }
554	}
555	
556	Fragment FragmentNode::Replicate(int repeats) const {
557	  ICHECK(repeats >= 1);
558	  Map<Var, PrimExpr> vmap;
559	  vmap.Set(ReplicationPlaceholder(),
560	           FloorMod(ReplicationPlaceholder(), ReplicateExtent()));
561	  PrimExpr new_forward_thread =
562	      Substitute(forward_thread_, vmap) +
563	      ThreadExtent() * FloorDiv(ReplicationPlaceholder(), ReplicateExtent());
564	  return Fragment(input_size_, forward_index_, new_forward_thread,
565	                  ReplicateExtent() * repeats, std::nullopt);
566	}
567	
568	Fragment FragmentNode::DeReplicate() const {
569	  ICHECK(OutputDim() == 1);
570	  arith::Analyzer analyzer;
571	  UpdateAnalyzer(&analyzer);
572	  int factor = 1;
573	  auto rep_size = as_const_int(ReplicateExtent());
574	  auto idx_size = as_const_int(OutputShape()[0]);
575	  if (rep_size && idx_size) {
576	    factor = arith::ZeroAwareGCD(*rep_size, *idx_size);
577	  }
578	  if (factor == 1)
579	    return GetRef<Fragment>(this);
580	
581	  Map<Var, PrimExpr> vmap;
582	  vmap.Set(ReplicationPlaceholder(), ReplicationPlaceholder() * factor +
583	                                         FloorMod(forward_index_[0], factor));
584	  PrimExpr new_forward_thread = Substitute(forward_thread_, vmap);
585	  Array<PrimExpr> new_forward_index = {FloorDiv(forward_index_[0], factor)};
586	  return Fragment(input_size_, new_forward_index, new_forward_thread,
587	                  int(*rep_size) / factor, std::nullopt)
588	      ->BindThreadRange(Range(0, ThreadExtent()));
589	}
