597	std::pair<Layout, arith::IterMapLevel>
598	LayoutNode::InverseWithLevel(bool require_padding_guard) const {
599	  arith::Analyzer analyzer;
600	  auto collect_symbolic = [&](const Array<PrimExpr> &shape) {
601	    Array<PrimExpr> symbolic_dims;
602	    for (const auto &dim : shape) {
603	      if (!as_const_int(dim)) {
604	        symbolic_dims.push_back(dim);
605	      }
606	    }
607	    return symbolic_dims;
608	  };
609	  Array<PrimExpr> symbolic_dims = collect_symbolic(input_size_);
610	  Array<PrimExpr> output_shape = OutputShape();
611	  symbolic_dims.insert(symbolic_dims.end(), output_shape.begin(),
612	                       output_shape.end());
613	  symbolic_dims = collect_symbolic(symbolic_dims);
614	  bool is_static_shape = symbolic_dims.empty();
615	  auto level = (is_static_shape && !require_padding_guard)
616	                   ? arith::IterMapLevel::Bijective
617	                   : arith::IterMapLevel::NoCheck;
618	  if (!is_static_shape) {
619	    // Runtime guards keep dynamic tails safe, so we allow NoCheck here and
620	    // warn.
621	    DLOG(WARNING) << "Layout::Inverse on symbolic layout, falling back to "
622	                     "NoCheck; symbolic dims: "
623	                  << symbolic_dims;
624	  }
625	  arith::IterMapResult res =
626	      arith::DetectIterMap(forward_index_, GetVarMap(), 1, level, &analyzer);
627	  if (!res->errors.empty()) {
628	    std::ostringstream msg;
629	    msg << "Layout " << DebugOutput() << " has errors: " << res->errors;
630	    throw NormalizeIterException(msg.str());
631	  }
632	
633	  auto outputs_shape = OutputShape();
634	  Array<PrimExpr> outputs;
635	  for (size_t i = 0; i < OutputDim(); i++) {
636	    outputs.push_back(InputPlaceholder(i));
637	  }
638	
639	  auto inv = arith::InverseAffineIterMap(res->indices, outputs);
640	
641	  Array<PrimExpr> backward_index;
642	  for (size_t i = 0; i < InputDim(); i++) {
643	    if (inv.find(InputPlaceholder(i)) != inv.end()) {
644	      backward_index.push_back(inv[InputPlaceholder(i)]);
645	    } else {
646	      backward_index.push_back(0);
647	    }
648	  }
649	
650	  return {Layout(outputs_shape, backward_index), level};
651	}
652	
653	Layout LayoutNode::Reshape(const Array<PrimExpr> &shape,
654	                           arith::Analyzer *analyzer,
655	                           const PrimExpr rescale_num,
656	                           const PrimExpr rescale_den) const {
657	
658	  // Fast path: if shape is the same, return the original layout
659	  if (StructuralEqual()(InputShape(), shape)) {
660	    return GetRef<Layout>(this);
661	  }
662	
663	  // Step 1. Prove the product relation holds under rescale:
664	  //   prod(InputShape) * rescale_num == prod(shape) * rescale_den
665	  PrimExpr input_shape_product = Integer(1);
666	  for (const auto &dim : InputShape()) {
667	    input_shape_product *= dim;
668	  }
669	  PrimExpr shape_product = Integer(1);
670	  for (const auto &dim : shape) {
671	    shape_product *= dim;
672	  }
673	
674	  // Use provided analyzer if present, otherwise a local fallback to avoid
675	  // potential null dereference paths flagged by static analysis.
676	  arith::Analyzer fallback_analyzer;
677	  arith::Analyzer *az = analyzer ? analyzer : &fallback_analyzer;
678	  ICHECK(az->CanProveEqual(input_shape_product * rescale_num,
679	                           shape_product * rescale_den))
680	      << "InputShape() = " << InputShape() << " shape = " << shape
681	      << ", rescale_num = " << rescale_num << ", rescale_den = " << rescale_den;
682	
683	  // The generic reshape below only reasons about a flat logical element index.
684	  // For subtype-changing views on packed sub-byte dtypes, that is not enough:
685	  // we must preserve which sub-element inside a packed storage slot is being
686	  // referenced.  Handle that first, then fall back to the ordinary reshape.
687	  if (auto packed =
688	          TryPackedSubtypeReshape(this, shape, az, rescale_num, rescale_den);
689	      packed.defined()) {
690	    return packed;
691	  }
692	
693	  // Step 2. Create new forward indices by reshaping
694	  Array<Var> new_vars = CreateReshapeVars(shape, az);
695	  // Step 3. Compute the flat index from new shape indices
696	  // flat_index = k0 * (s1 * s2 * ...) + k1 * (s2 * s3 * ...) + ... + kn
697	  PrimExpr flat_index = ComputeFlatIndex(shape, new_vars);
698	  // Convert new flat index (in units of new elements) to the old flat index
699	  // (in units of old elements) using the rational rescale factor.
700	  // old_flat = floor((flat_index * rescale_den) / rescale_num)
701	  PrimExpr old_flat_index = floordiv(flat_index * rescale_den, rescale_num);
702	  Array<PrimExpr> original_indices =
703	      RecoverOriginalIndices(InputShape(), old_flat_index);
704	  // Step 5. Substitute original indices into forward_index_
705	  Array<PrimExpr> new_forward_index = SubstituteForwardIndex(
706	      forward_index_, InputShape(), original_indices, az);
707	  new_forward_index = RestoreInputPlaceholders(new_forward_index, new_vars);
708	  return Layout(shape, new_forward_index);
709	}
710	
711	Layout FragmentNode::Reshape(const Array<PrimExpr> &shape,
712	                             arith::Analyzer *analyzer,
713	                             const PrimExpr rescale_num,
714	                             const PrimExpr rescale_den) const {
715	
716	  // Fast path: identical input shape, return self
717	  if (StructuralEqual()(InputShape(), shape)) {
718	    return GetRef<Fragment>(this);
719	  }
720	
721	  // 1) Prove total number of elements remains the same
722	  PrimExpr input_prod = Integer(1);
723	  for (const auto &d : InputShape())
724	    input_prod *= d;
725	  PrimExpr shape_prod = Integer(1);
726	  for (const auto &d : shape)
727	    shape_prod *= d;
728	
729	  // Use provided analyzer if present, otherwise a local fallback.
730	  arith::Analyzer fallback_analyzer;
731	  arith::Analyzer *az = analyzer ? analyzer : &fallback_analyzer;
732	  ICHECK(az->CanProveEqual(input_prod * rescale_num, shape_prod * rescale_den))
733	      << "InputShape() = " << InputShape() << " shape = " << shape
734	      << ", rescale_num = " << rescale_num << ", rescale_den = " << rescale_den
735	      << " input fragment layout is = " << DebugOutput();
736	
737	  // Fragments need the same special handling as plain layouts so that packed
738	  // subtype views keep a stable thread/data mapping through reshape.
739	  if (auto packed =
740	          TryPackedSubtypeReshape(this, shape, az, rescale_num, rescale_den);
741	      packed.defined()) {
742	    return packed;
743	  }
744	
745	  // 2) Build flat index from new-shape indices
746	  Array<Var> new_vars = CreateReshapeVars(shape, az);
747	  PrimExpr flat = ComputeFlatIndex(shape, new_vars);
748	  // Convert to old flat index units using the rational rescale factor.
749	  // old_flat = floor((flat * rescale_den) / rescale_num)
750	  PrimExpr old_flat = floordiv(flat * rescale_den, rescale_num);
751	  // 3) Recover original indices from flat index
752	  Array<PrimExpr> orig_indices = RecoverOriginalIndices(InputShape(), old_flat);
753	  // 4) Substitute old placeholders with expressions of new indices
754	  Array<PrimExpr> new_forward_index =
755	      SubstituteForwardIndex(forward_index_, InputShape(), orig_indices, az);
756	  PrimExpr new_forward_thread =
757	      SubstituteReshapedExpr(forward_thread_, InputShape(), orig_indices, az);
758	  new_forward_index = RestoreInputPlaceholders(new_forward_index, new_vars);
759	  new_forward_thread = RestoreInputPlaceholders(new_forward_thread, new_vars);
760	  Fragment reshaped(shape, new_forward_index, new_forward_thread,
761	                    ReplicateExtent(), std::nullopt);
762	  if (thread_range_.defined()) {
763	    reshaped = reshaped->BindThreadRange(thread_range_);
764	  }
765	  return reshaped;
766	}
