773	PrimExpr infer_fragment_index(const Map<Var, Range> &input_iters,
774	                              const PrimExpr &forward_thread,
775	                              arith::Analyzer *analyzer) {
776	  // we build iter_vars from input_iters, but set _rep to range [0, 1)
777	  // to make it not contribute to the index of the forward_idx
778	  Array<IterVar> iter_vars;
779	  for (const auto &[var, range_] : input_iters) {
780	    Range range = range_;
781	    if (var.same_as(ReplicationPlaceholder())) {
782	      range = Range(0, 1);
783	    }
784	    iter_vars.push_back(IterVar(range, var, IterVarType::kDataPar));
785	  }
786	
787	  Array<arith::IterSplitExpr> splits =
788	      DivideUnusedIterators({forward_thread}, iter_vars, analyzer);
789	  return MakeFlattenedExpression(splits);
790	}
