792	FragmentNode::FragmentNode(Array<PrimExpr> input_size,
793	                           Array<PrimExpr> forward_index,
794	                           PrimExpr forward_thread, PrimExpr replicate_size) {
795	  input_size_ = input_size;
796	  replicate_size_ = replicate_size;
797	  arith::Analyzer analyzer;
798	  UpdateAnalyzer(&analyzer);
799	  forward_thread_ = analyzer.Simplify(forward_thread);
800	  if (forward_index.empty()) {
801	    forward_index = {
802	        infer_fragment_index(GetVarMap(), forward_thread_, &analyzer)};
803	  }
804	  forward_index_ = forward_index.Map(
805	      [&](const PrimExpr &e) { return analyzer.Simplify(e); });
