808	Fragment::Fragment(Array<IterVar> forward_var, Array<PrimExpr> forward_index,
809	                   PrimExpr forward_thread, IterVar thread_replicate) {
810	  Map<Var, PrimExpr> vmap;
811	  Array<PrimExpr> input_size;
812	  PrimExpr replicate_size = 1;
813	  for (size_t i = 0; i < forward_var.size(); i++) {
814	    vmap.Set(forward_var[i]->var, InputPlaceholder(i));
815	    ICHECK(is_zero(forward_var[i]->dom->min));
816	    input_size.push_back(forward_var[i]->dom->extent);
817	  }
818	  if (thread_replicate.defined()) {
819	    ICHECK(is_zero(thread_replicate->dom->min));
820	    replicate_size = thread_replicate->dom->extent;
821	    vmap.Set(thread_replicate->var, ReplicationPlaceholder());
822	  }
823	  forward_index =
824	      forward_index.Map([&](const PrimExpr &e) { return Substitute(e, vmap); });
825	  forward_thread = Substitute(forward_thread, vmap);
826	
827	  auto n = make_object<FragmentNode>(input_size, forward_index, forward_thread,
828	                                     replicate_size);
829	  data_ = std::move(n);
830	}
