832	Fragment::Fragment(Array<PrimExpr> input_size, Array<PrimExpr> forward_index,
833	                   PrimExpr forward_thread, PrimExpr replicate_size,
834	                   Optional<Var> replicate_var) {
835	  if (replicate_var.defined()) {
836	    forward_thread = Substitute(
837	        forward_thread, {{replicate_var.value(), ReplicationPlaceholder()}});
838	  }
839	  auto n = make_object<FragmentNode>(input_size, forward_index, forward_thread,
840	                                     replicate_size);
841	  data_ = std::move(n);
842	}
