858	arith::IterMapResult
859	FragmentNode::DetectInjective(bool require_padding_guard) const {
860	  // To check that the forward map is injective, reverse it and verify that the
861	  // recovered coordinates remain independent. require_padding_guard is only
862	  // used by generated full-block loop partitions whose mapping is known
863	  // injective but whose padded domain is rejected by stricter iter-map checks.
864	  arith::Analyzer analyzer;
865	  // Build a flat indices array: [forward_thread_, forward_index_[...]]
866	  Array<PrimExpr> indices;
867	  indices.push_back(forward_thread_);
868	  for (const auto &e : forward_index_) {
869	    indices.push_back(e);
870	  }
871	
872	  // Mirror Layout::InverseWithLevel(): if any participating shape is
873	  // symbolic, relax to NoCheck and rely on runtime guards elsewhere.
874	  auto collect_symbolic = [&](const Array<PrimExpr> &shape) {
875	    Array<PrimExpr> symbolic_dims;
876	    for (const auto &dim : shape) {
877	      if (!as_const_int(dim)) {
878	        symbolic_dims.push_back(dim);
879	      }
880	    }
881	    return symbolic_dims;
882	  };
883	
884	  Array<PrimExpr> symbolic_dims = collect_symbolic(InputShape());
885	  Array<PrimExpr> output_shape = OutputShape();
886	  symbolic_dims.insert(symbolic_dims.end(), output_shape.begin(),
887	                       output_shape.end());
888	  // Also consider replicate size for fragments
889	  if (!as_const_int(ReplicateExtent())) {
890	    symbolic_dims.push_back(ReplicateExtent());
891	  }
892	  symbolic_dims = collect_symbolic(symbolic_dims);
893	
894	  bool is_static_shape = symbolic_dims.empty();
895	  auto level = (is_static_shape && !require_padding_guard)
896	                   ? arith::IterMapLevel::Bijective
897	                   : arith::IterMapLevel::NoCheck;
898	  if (!is_static_shape) {
899	    DLOG(WARNING)
900	        << "Fragment::DetectInjective on symbolic layout, falling back to "
901	        << "NoCheck; symbolic dims: " << symbolic_dims;
902	  }
903	
904	  return arith::DetectIterMap(indices, GetVarMap(), 1, level, &analyzer);
905	}
