907	PrimExpr FragmentNode::ThreadExtent() const {
908	  Array<PrimExpr> ret(OutputDim(), 1);
909	  arith::Analyzer analyzer;
910	  UpdateAnalyzer(&analyzer);
911	  auto ist = analyzer.int_set(forward_thread_ + 1);
912	  return ist.max();
913	}
