926	PrimExpr FragmentNode::ForwardThread(const Array<PrimExpr> &vars,
927	                                     const Optional<PrimExpr> &rep_var) const {
928	  Map<Var, PrimExpr> vmap;
929	  ICHECK_EQ(vars.size(), InputDim());
930	  for (size_t i = 0; i < InputDim(); i++) {
931	    vmap.Set(InputPlaceholder(i), vars[i]);
932	  }
933	  if (rep_var.defined())
934	    vmap.Set(ReplicationPlaceholder(), rep_var.value());
935	
936	  return Substitute(forward_thread_, vmap);
937	}
