944	std::pair<Layout, arith::IterMapLevel>
945	FragmentNode::InverseWithLevel(bool require_padding_guard) const {
946	  auto input_size_copy = input_size_;
947	  input_size_copy.push_back(ReplicateExtent());
948	  auto forward_index_copy = forward_index_;
949	  forward_index_copy.push_back(
950	      Substitute(forward_thread_,
951	                 {{ReplicationPlaceholder(), InputPlaceholder(InputDim())}}));
952	  auto fwd = Layout(input_size_copy, forward_index_copy);
953	  return fwd->InverseWithLevel(require_padding_guard);
954	}
