956	Fragment FragmentNode::CondenseReplicateVar() const {
957	  arith::Analyzer analyzer;
958	  auto input_iters = GetVarMap();
959	  input_iters.Set(ReplicationPlaceholder(), {0, ReplicateExtent()});
960	  PrimExpr new_forward_thread;
961	  IterVar new_thread_replicate;
962	  std::tie(new_forward_thread, new_thread_replicate) =
963	      CompressIterator(forward_thread_, ToIterVars(input_iters),
964	                       ReplicationPlaceholder(), &analyzer);
965	  return Fragment(input_size_, forward_index_, new_forward_thread,
966	                  new_thread_replicate->dom->extent, new_thread_replicate->var);
967	}
