990	bool LayoutNode::IsEqual(const LayoutNode *other, bool skip_index) const {
991	  bool ret = StructuralEqual()(this->InputShape(), other->InputShape());
992	  ret &= StructuralEqual()(this->OutputShape(), other->OutputShape());
993	  if (!ret) {
994	    return false;
995	  }
996	  if (!skip_index) {
997	    // Create common variables for comparison. Using Forward with common
998	    // variables ensures we compare the actual mapping rather than AST
999	    // structure, since InputPlaceholder may compare equal in StructuralEqual.
1000	    Array<PrimExpr> common_vars;
1001	    for (size_t i = 0; i < this->InputDim(); i++) {
1002	      common_vars.push_back(Var("_cmp_v" + std::to_string(i)));
1003	    }
1004	
1005	    auto this_forward = this->Forward(common_vars);
1006	    auto other_forward = other->Forward(common_vars);
1007	
1008	    if (!StructuralEqual()(this_forward, other_forward)) {
1009	      return false;
1010	    }
1011	  }
1012	  return ret;
1013	}
1014	
1015	bool FragmentNode::IsEqual(const FragmentNode *other, bool skip_index) const {
1016	  // Fragment Layout Comparison can skip the index comparison
1017	  // when the output shape is the same, as we can do
1018	  // a[i, j] = b[j, i] in register level.
1019	
1020	  bool ret = StructuralEqual()(this->InputShape(), other->InputShape());
1021	  if (!ret) {
1022	    // may be broadcast case
1023	    return true;
1024	  }
1025	  if (this->thread_range_.defined() && other->thread_range_.defined()) {
1026	    ret &= StructuralEqual()(this->thread_range_, other->thread_range_);
1027	  }
1028	  ret &= StructuralEqual()(this->OutputShape(), other->OutputShape());
1029	  ret &= StructuralEqual()(this->ReplicateExtent(), other->ReplicateExtent());
1030	  ret &= StructuralEqual()(this->ThreadExtent(), other->ThreadExtent());
1031	  if (!ret) {
1032	    return false;
1033	  }
1034	  if (!skip_index) {
1035	    // Create common variables for comparison. Using Forward/ForwardThread with
1036	    // common variables ensures we compare the actual mapping rather than AST
1037	    // structure, since InputPlaceholder may compare equal in StructuralEqual.
1038	    Array<PrimExpr> common_vars;
1039	    for (size_t i = 0; i < this->InputDim(); i++) {
1040	      common_vars.push_back(Var("_cmp_v" + std::to_string(i)));
1041	    }
1042	    Var common_rep("_cmp_rep");
1043	
1044	    auto this_forward = this->Forward(common_vars);
1045	    auto other_forward = other->Forward(common_vars);
1046	
1047	    if (!StructuralEqual()(this_forward, other_forward)) {
1048	      return false;
1049	    }
1050	
1051	    // Also compare forward_thread mapping.
1052	    auto this_thread = this->ForwardThread(common_vars, common_rep);
1053	    auto other_thread = other->ForwardThread(common_vars, common_rep);
1054	    if (!StructuralEqual()(this_thread, other_thread)) {
1055	      return false;
1056	    }
1057	  }
1058	  return ret;
1059	}
