68	  // Repeat the layout along a single input dimension and prepend a new output
69	  // dimension that indicates the repeat-group index.
70	  //
71	  // For a layout L with input shape S and forward index F, repeating along
72	  // dimension `dim` with `factor` constructs a new layout L' where:
73	  //   - New input shape: S'[dim] = S[dim] * factor
74	  //   - New forward index: [i_dim // S[dim]] + F(..., i_dim % S[dim], ...)
75	  virtual Layout Repeat(int dim, int factor) const;
76	
77	  // Expand (lift) this layout by prepending new leading input dimensions that
78	  // are forwarded unchanged to the output.
79	  //
80	  // For example, given a 2D layout L: [J, K] -> F(J, K), calling
81	  // Expand([I]) produces a 3D layout L': [I, J, K] -> [I] + F(J, K).
82	  //
83	  // `leading_shape` can contain multiple dimensions.
84	  virtual Layout Expand(const ffi::Array<PrimExpr> &leading_shape) const;
85	
86	  virtual Layout Inverse() const;
87	
88	  // Reshape the layout to a new logical shape. When aliasing buffers of
89	  // different dtypes, the element count may change while the underlying
90	  // storage footprint stays equal. Use rescale_num/rescale_den to represent
91	  // the ratio between the old element size and the new element size in bits.
92	  // Specifically, define factor = rescale_num / rescale_den where:
93	  //   new_num_elems = old_num_elems * factor
94	  // For example, f32->i8 (32b -> 8b) uses rescale_num=32, rescale_den=8.
95	  // i8->f32 (8b -> 32b) uses rescale_num=8, rescale_den=32.
96	  // For sub-byte subtype views, the output layout may temporarily gain or drop
97	  // a trailing "pack lane" dimension so that the layout still describes how
98	  // multiple logical elements share the same physical storage slot.
99	  virtual Layout Reshape(const ffi::Array<PrimExpr> &shape,
100	                         arith::Analyzer *analyzer = nullptr,
101	                         const PrimExpr rescale_num = Integer(1),
102	                         const PrimExpr rescale_den = Integer(1)) const;
103	
104	  virtual std::pair<Layout, arith::IterMapLevel>
105	  InverseWithLevel(bool require_padding_guard = false) const;
106	
107	  virtual std::string DebugOutput() const;
108	
109	  virtual bool IsEqual(const LayoutNode *other, bool skip_index = false) const;
110	
111	  static void RegisterReflection();
112	  TVM_FFI_DECLARE_OBJECT_INFO("tl.Layout", LayoutNode, ffi::Object);
113	  static constexpr TVMFFISEqHashKind _type_s_eq_hash_kind =
114	      kTVMFFISEqHashKindTreeNode;
