38	Fragment makeGemmFragment8x4() {
39	  IterVar i = MakeIterVar("i", 8);
40	  IterVar j = MakeIterVar("j", 4);
41	  IterVar rep = MakeIterVar("rep", 1);
42	  PrimExpr forward_thread = FloorDiv(j->var, 1) + 4 * i;
43	  PrimExpr index = FloorMod(j->var, 1);
44	  return Fragment({i, j}, {index}, forward_thread, rep);
