  PrimExpr phase = FloorMod(FloorDiv(row, perPhase), maxPhase);
  PrimExpr colOffSwizzled = (FloorDiv(col, vecSize) ^ phase) * vecSize;
  PrimExpr colOffOrdered = FloorMod(col, vecSize);

